export function wrapModItem(
	data: T.ModItem & { readonly $other?: T.ModItem | readonly T.ModItem[] },
	tree: TreeHandle
): T.ModItem.Parsed {
	if (typeof data === 'number') return data as unknown as T.ModItem.Parsed;
	const node = _keepModelledSlots(data, ['_mod_item_external', '_mod_item_inline']);
	const kindKeyed = _firstKindKeyedWrapChild(node, ['mod_item_external', 'mod_item_inline']) as
		| T.ModItem
		| readonly T.ModItem[]
		| undefined;
	const filtered = kindKeyed ?? _filterWrapChildrenByKind(node.$other, ['mod_item_external', 'mod_item_inline']);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.ModItem>(node as T.ModItem, tree) as unknown as T.ModItem.Parsed;
	}
	return hydrateChild<T.ModItem>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

