export function wrapImplItem(
	data: T.ImplItem & { readonly $other?: T.ImplItem | readonly T.ImplItem[] },
	tree: TreeHandle
): T.ImplItem.Parsed {
	if (typeof data === 'number') return data as unknown as T.ImplItem.Parsed;
	const node = _keepModelledSlots(data, ['_impl_item_body', '_impl_item_semi']);
	const kindKeyed = _firstKindKeyedWrapChild(node, ['impl_item_body', 'impl_item_semi']) as
		| T.ImplItem
		| readonly T.ImplItem[]
		| undefined;
	const filtered = kindKeyed ?? _filterWrapChildrenByKind(node.$other, ['impl_item_body', 'impl_item_semi']);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.ImplItem>(node as T.ImplItem, tree) as unknown as T.ImplItem.Parsed;
	}
	return hydrateChild<T.ImplItem>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

